-- ESTEQO - refresh the treatment menu
--
-- USE THIS ONLY when you have edited react-app/src/data (menu.js, brows.js,
-- bridal.js) and want the database to match the website again.
--
-- WHAT IT DOES: replaces service_categories and services.
-- WHAT IT LEAVES ALONE: blog posts, FAQs, team, testimonials, settings, and
-- every enquiry in contacts / appointments / newsletter_subscribers.
--
-- Nothing you wrote at /admin/blog is affected.
--
-- Regenerate this file after editing the menu:
--   node scripts/gen-seed.mjs      (see the project README)

SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM `services`;
DELETE FROM `service_categories`;



SET FOREIGN_KEY_CHECKS = 1;
